			var sourceRow = GetTNTCustomsDataRow(@"100WW193878238      999001001PERSONAL EFFECT ADDITIONALTEXT                                                                                                                                                                                                   0000040000000   N             THB   USDUSD                                                    EX               00088000    000          ADDRESS   00088000TH 680THAILAND                                                                                                        0000000000000                                                                                  0000001330888                                                                        990500                                          000000000400000008   HKT  LIN  HKT  QPZ  BG5                               0000000000000               Y   000                              201012101456CIFPIACENZA                8   THB                                                                20101220G  NN                                                                                          PERSONAL EFFECT                   0000000000000R 0000001000880000008800040000010008800000088            CTCARTON              48N   NY S00004    0000040000000000007555900134/13 PRACHANUKROH ROAD,                                                                  KATHU                         TH 680THAILAND                      PRAPHUT               076    344687   MVS010023329ANGELINA TRAVEL & TOUR                            83150    PHUKET                                                        VIA FULGOSIO 17A                                                                          PIACENZA                      IT 005ITALY                                                                           SIMONA BAZZONI MS                                 29100    PC                                                                                                                                                                                       000                                                                                                                                                                                                                                                                                                                                    000                                                                                                                                                                                                             201012122359WW   000                                 000                              KL AMS  20101212                                                       07446126371         0878    BKK                      A0A O  S                 USD                                               TH 680THAILAND                      BANGKOK  AIR HUB              999 M 7  RACHATHEWA           SUVARNABHUMI INT L CUSTOMS    T201 WFS-PG CARGO BUILDIN     10540    BANG PHLI                     TNT EXPRESS WORLDWIDE CO  LTD                                                                 BANGKOK                       XDCSFM");
			AssertNoExceptionThrown(() => new AWBImporter().CreateMAWB(currentWebUser, Factory, sourceRow));
		}

		public void TestValidateCorrectFile()
		{
			List<string> dataList = GetTestDataList();
			var dataStream = GetDataStream(dataList);

			var dummyLogger = new DummyLogger();
			AWBImporter importer = new AWBImporter();
			var processedInfo = importer.Validate(currentWebUser, dataStream, dummyLogger);

			AssertEquals("Info Messages", @"Validating Quantum File with size: 67234 bytes
MAWB processed: 074-46126371
HAWB processed: 193878238
HAWB processed: 207301059
HAWB processed: 252614702
HAWB processed: 252614716
HAWB processed: 255931341
HAWB processed: 259272313
HAWB processed: 259272327
HAWB processed: 262145938
HAWB processed: 292217505
HAWB processed: 329384101
HAWB processed: 331868528
HAWB processed: 334571699
HAWB processed: 335036763
HAWB processed: 335040771
HAWB processed: 335040785
HAWB processed: 356192738
HAWB processed: 356193203
HAWB processed: 863626288
HAWB processed: 863626291
HAWB processed: 962250847
HAWB processed: 966630655
MAWB and HAWBs successfully validated.", dummyLogger.InfoMessages.Trim());
			AssertEquals("Error Messages", "", dummyLogger.ErrorMessages);

			AssertEquals("MAWBNumber returned", "074-46126371", processedInfo.MAWBNumber);
			AssertEquals("DischargePort", "AMS", processedInfo.DestinationPort);
			AssertEquals("FlightDate", "20101212", processedInfo.FlightDate);
			AssertEquals("HAWBNumbers.Count", 21, processedInfo.HAWBNumbers.Count);
		}

		public void TestValidateBadRecordType()
		{
			List<string> dataList = new List<string>();
			dataList.Add("111" + @"WW193878238      999001001PERSONAL EFFECT                                                                                                                                                                                                                  0000040000000   N             THB   USDUSD                                                    EX               00088000    000          ADDRESS   00088000TH 680THAILAND                                                                                                        0000000000000                                                                                  0000001330888                                                                        990500                                          000000000400000008   HKT  LIN  HKT  QPZ  BG5                               0000000000000               Y   000                              201012101456CIFPIACENZA                8   THB                                                                20101220G  NN                                                                                          PERSONAL EFFECT                   0000000000000R 0000001000880000008800040000010008800000088            CTCARTON              48N   NY S00004    0000040000000000007555900134/13 PRACHANUKROH ROAD,                                                                  KATHU                         TH 680THAILAND                      PRAPHUT               076    344687   MVS010023329ANGELINA TRAVEL & TOUR                            83150    PHUKET                                                        VIA FULGOSIO 17A                                                                          PIACENZA                      IT 005ITALY                                                                           SIMONA BAZZONI MS                                 29100    PC                                                                                                                                                                                       000                                                                                                                                                                                                                                                                                                                                    000                                                                                                                                                                                                             201012122359WW   000                                 000                              KL AMS  20101212                                                       07446126371         0878    BKK                      A0A O  S                 USD                                               TH 680THAILAND                      BANGKOK  AIR HUB              999 M 7  RACHATHEWA           SUVARNABHUMI INT L CUSTOMS    T201 WFS-PG CARGO BUILDIN     10540    BANG PHLI                     TNT EXPRESS WORLDWIDE CO  LTD                                                                 BANGKOK                       XDCSFM");
			var dataStream = GetDataStream(dataList);

			var dummyLogger = new DummyLogger();
			AWBImporter importer = new AWBImporter();
			var processedInfo = importer.Validate(currentWebUser, dataStream, dummyLogger);

			AssertEquals("Info Messages", @"Validating Quantum File with size: 3202 bytes
Validation failed.", dummyLogger.InfoMessages.Trim());
			AssertEquals("Error Messages", @"File contains the wrong RECORD_TYPE. 100 is the expected value.
", dummyLogger.ErrorMessages);

			AssertEquals("MAWBNumber returned", "", processedInfo.MAWBNumber);
			AssertEquals("DischargePort", "", processedInfo.DestinationPort);
			AssertEquals("FlightDate", "", processedInfo.FlightDate);
			AssertEquals("HAWBNumbers.Count", 0, processedInfo.HAWBNumbers.Count);
		}

