			AssertEquals("AWBRateLine1.ER_NatureAndQtyOfGoods", "PERSONAL EFFECT ADDITIONALTEXT", header.AWBRateLine1.NatureAndQtyOfGoodsDescription); // CON_GOODS_DS

			AssertEquals("EH_ShippingLoadAndCount", 4, header.EH_ShippingLoadAndCount); //CON_TOT_PIECE_QT

			AssertEquals("AWBRateLines.Count", 12, header.AWBRateLines.Count);
			AssertEquals("ER_GrossWeight", 88.000M, header.AWBRateLines[0].ER_GrossWeight); //CON_OPSA_TGRS_WT
			AssertEquals("ER_ChargeableWeight", 0.000M, header.AWBRateLines[0].ER_ChargeableWeight); // Not Filled In
			AssertEquals("ER_WeightInLBsOrKGs", "K", header.AWBRateLines[0].ER_WeightInLBsOrKGs); //hard coded
			AssertEquals("ER_NoOfPiecesOrRCP", "4", header.AWBRateLines[0].ER_NoOfPiecesOrRCP); //CON_TOT_PIECE_QT

			AssertEquals("EH_IssuingAgentName", "KLM Royal Dutch Airlines", header.EH_IssuingAgentName);  //Use MOV-CRR-ID to look up the two char code in refairline table.
			AssertEquals("EH_IssuingAgentAddress1", "P.O. Box 7700", header.EH_IssuingAgentAddress1);  //RefAirline.RM_AddressLine1
			AssertEquals("EH_IssuingAgentAddress1", "Schiphol Airport, Amsterdam, 1117 ZL", header.EH_IssuingAgentAddress2);  //RefAirline.RM_AddressLine2 + RM_AirlineCity + RM_AirlinePostalCode

			AssertEquals("EH_AirportOfDepartureAndRequestRouteText", "BKK", header.EH_AirportOfDepartureAndRequestRouteText);  //MOV_ORIG_BUL_ID
			AssertEquals("EH_To1st", "AMS", header.EH_To1st); //MOV_ORIG_BUL_ID
			AssertEquals("EH_By1st", "KL", header.EH_By1st); //MOV-CRR-ID
			AssertEquals("EH_By1st", "KL", header.EH_Booking1stCarrier); //MOV-CRR-ID
			AssertEquals("EH_Booking1stFlight", "0878", header.EH_Booking1stFlight); //MOV-NR
			AssertEquals("EH_Booking1stFlightDate", "12", header.EH_Booking1stFlightDate); //MOV-DEP-DT, extract the date portion (last 2 chars).
			AssertEquals("EH_To2nd", "", header.EH_To2nd); //if MOV_COU_DES2 is not blank, meaning there is 2nd flight, then this field equates MOV-DEST-BUL-ID
			AssertEquals("EH_By2nd", "", header.EH_By2nd); //if MOV_COU_DES2 is not blank, then set to MOV-CRR-ID  assuming same carrier, as no other carrier field is provided in source file.

			AssertEquals("EH_Currency", "USD", header.EH_Currency); //LAV_VALUE_DS1
			AssertEquals("EH_ShippersSignature", "", header.EH_ShippersSignature);  // Should be nothing at the HAWB Level

			AssertEquals("ParentBill", mawbheader, header.ParentBill);

			AssertEquals("EH_WeightPrepaidCollect", ExportAWBHeader.Constants.PrepaidCollect1CharCodes.Prepaid, header.EH_WeightPrepaidCollect);
			AssertEquals("EH_OtherPrepaidCollect", ExportAWBHeader.Constants.PrepaidCollect1CharCodes.Prepaid, header.EH_OtherPrepaidCollect);
		}

		[DatCapabilityRequirement("SOURCE_CODE")]
		[StressTest]
		public void TestImportingMultipleFiles()
		{
			List<string> fileList = new List<string>();
			fileList.Add("0810864.txt");
			fileList.Add("3916091.txt");
			fileList.Add("8695101.txt");
			fileList.Add("LogisticServices/content/Forwarding/TestFiles/tnt-fhl-20101227-082318.txt");
			fileList.Add("tnt-fhl-20101227-090821.txt");
			fileList.Add("LogisticServices/content/Forwarding/TestFiles/TNT-FHL-20101227-113757.txt");
			fileList.Add("tnt-fhl-20101227-152400.txt");
			fileList.Add("tnt-fhl-20101227-162637.txt");

			foreach (var filename in fileList)
			{
				using (var fileStream = LoadTestFileAsStream(filename))
				{
					var importer = new AWBImporter();
					var logger = new DummyLogger();
					var info = importer.Import(currentWebUser, fileStream, logger);

					if (!info.ErrorsFound)
					{
						CombineAssertions(delegate
						{
							var mawbHeader = Factory.Load<ExportAWBHeader>(info.MAWBRecordPK);
							foreach (ExportAWBHeader hawbHeader in mawbHeader.ChildBills)
							{
								var childLogger = new DummyLogger();
								ValidateFHLRequiredFields(hawbHeader, childLogger);
								AssertEquals("Warnings for " + filename + " " + hawbHeader.EH_WayBillNumber, "", childLogger.WarningMessages);
							}
						});
					}
				}
			}
		}

		static readonly HashSet<string> TestFilesGetFromAssets = new()
		{
			"LogisticServices/content/Forwarding/TestFiles/tnt-fhl-20101227-082318.txt",
			"LogisticServices/content/Forwarding/TestFiles/TNT-FHL-20101227-113757.txt"
		};

		Stream LoadTestFileAsStream(string fileName)
		{
			string filePath = TestFilesGetFromAssets.Contains(fileName) ? AssetsHelper.FetchTestAsset(fileName) : resourceRetriever.SaveResourceToFile(fileName);
			return File.OpenRead(filePath);
		}

		#region Implementation

		class DummyLogger : IImportLogger
		{
			public string InfoMessages
			{
				get
				{
					return infoMessages.ToString();
				}
			}

			readonly StringBuilder infoMessages = new StringBuilder();

			public string ErrorMessages
			{
				get
				{
					return errorMessages.ToString();
				}
			}

			readonly StringBuilder errorMessages = new StringBuilder();

			public string WarningMessages
			{
				get
				{
					return warningMessages.ToString();
				}
			}

			readonly StringBuilder warningMessages = new StringBuilder();

			#region IImportLogger Members

			public void LogInfo(string message)
			{
				infoMessages.AppendLine(message);
			}

			public void LogError(string message)
			{
				errorMessages.AppendLine(message);
			}

			public void LogWarning(string message)
			{
				warningMessages.AppendLine(message);
			}

			#endregion
		}

		void ValidateRequiredMessagingField(IImportLogger logger, ZPropertyInfo fieldInfo)
		{
			if (fieldInfo.Value.IsEmpty)
			{
				logger.LogWarning(string.Format("Field {0} required for FHL, but is not provided.", fieldInfo.Name));
			}
		}

		void ValidateFHLRequiredFields(ExportAWBHeader hawbHeader, IImportLogger logger)
		{
			ValidateRequiredMessagingField(logger, hawbHeader.EH_WayBillNumberInfo);
			ValidateRequiredMessagingField(logger, hawbHeader.EH_AWBOriginCodeInfo);
			ValidateIATAPortCode(logger, hawbHeader.EH_AWBOriginCodeInfo);

			ValidateRequiredMessagingField(logger, hawbHeader.EH_AirportOfDestinationCodeInfo);
			ValidateIATAPortCode(logger, hawbHeader.EH_AirportOfDestinationCodeInfo);

			ValidateRequiredMessagingField(logger, hawbHeader.AWBRateLines[0].ER_NoOfPiecesOrRCPInfo);
			ValidateRequiredMessagingField(logger, hawbHeader.AWBRateLines[0].ER_WeightInLBsOrKGsInfo);
			ValidateRequiredMessagingField(logger, hawbHeader.AWBRateLines[0].ER_GrossWeightInfo);
			ValidateRequiredMessagingField(logger, hawbHeader.EH_ShippingLoadAndCountInfo);
			ValidateRequiredMessagingField(logger, hawbHeader.AWBRateLines[0].ER_NatureAndQtyOfGoodsInfo);

			ValidateRequiredMessagingField(logger, hawbHeader.EH_ShipperNameInfo);
			ValidateRequiredMessagingField(logger, hawbHeader.EH_ShipperAddressInfo);
			ValidateRequiredMessagingField(logger, hawbHeader.EH_ShipperPlaceInfo);
			ValidateRequiredMessagingField(logger, hawbHeader.EH_ShipperCountryCodeInfo);
			ValidateCountryCode(logger, hawbHeader.EH_ShipperCountryCodeInfo);

			ValidateRequiredMessagingField(logger, hawbHeader.EH_ConsigneeNameInfo);
			ValidateRequiredMessagingField(logger, hawbHeader.EH_ConsigneeAddressInfo);
			ValidateRequiredMessagingField(logger, hawbHeader.EH_ConsigneePlaceInfo);
			ValidateRequiredMessagingField(logger, hawbHeader.EH_ConsigneeCountryCodeInfo);
			ValidateCountryCode(logger, hawbHeader.EH_ConsigneeCountryCodeInfo);
		}

		void ValidateCountryCode(IImportLogger logger, ZPropertyInfo fieldInfo)
		{
			var countries = Factory.Load<RefCountry>(new ZQuery(RefCountrySchema.RN_Code, fieldInfo.Value));

			if (countries.Length == 0)
			{
				logger.LogWarning(string.Format("Field {0} provided country code {1}, but is not found in RefCountry Table.", fieldInfo.Name, fieldInfo.Value));
			}
		}

		void ValidateIATAPortCode(IImportLogger logger, ZPropertyInfo fieldInfo)
		{
			var unlocos = Factory.Load<RefUNLOCO>(new ZQuery(RefUNLOCOSchema.RL_IATA, fieldInfo.Value));

			if (unlocos.Length == 0)
			{
				logger.LogWarning(string.Format("Field {0} provided IATA code {1}, but is not found in RefUNLOCO Table.", fieldInfo.Name, fieldInfo.Value));
			}
		}

		TNTCustomsRowData GetTNTCustomsDataRow(string dataLine)
		{
			var rowData = new TNTCustomsRowData();
			rowData.ReadRow(dataLine);
			return rowData;
		}

